	if nums1 == nil || nums2 == nil || len(nums1) == 0 || len(nums2) == 0 {
		return nil
	}
	m := make(map[int]struct{})
	ans := make(map[int]struct{})
	for _, v := range nums1 {
		m[v] = struct{}{}
	}

	for _, v := range nums2 {
		if _, ok := m[v]; ok {
			ans[v] = struct{}{}
		}
	}
	ansSlice := []int{}
	for k, _ := range ans {
		ansSlice = append(ansSlice, k)
	}
	return ansSlice
}

